        let noncontiguous = vec![hydrated_file(&["gap"], 1, 3)];
        assert!(
            materialize_sorafs_payload_files(
                payload,
                &noncontiguous,
                &target_root,
                8,
                1_024,
                1_024,
            )
            .is_err()
        );
        assert_eq!(fs::read(target_root.join("marker"))?, b"live-state");
        assert_eq!(fs::read_dir(&target_root)?.count(), 1);
