        let oversized = temp_dir.path().join("inrou-oversized-output");
        fs::write(
            &oversized,
            "#!/bin/sh\ni=0\nwhile [ \"$i\" -lt 70000 ]; do printf x; i=$((i + 1)); done\n",
        )?;
